using OricOffice.Core;
using OricOffice.Core.Model;
using OricOffice.Core.Services;
using OricOffice.Core.Storage;
using OricOffice.Core.ViewModels;

namespace OricOffice.Core.Tests;

/// <summary>
/// Proves the new version imports the suite's file formats: committed fixtures
/// (generated by tools/FixtureGen) must load at store level AND through every
/// module's view model, preserving each section for cross-module round-trips.
/// </summary>
public class FixtureImportTests : IDisposable
{
    private readonly TempDir _dir = new();
    private readonly FakeDialogs _dialogs = new();
    private readonly FakeLifetime _lifetime = new();
    private readonly FakeClipboard _clipboard = new();
    private readonly OricFileStore _store;

    public FixtureImportTests() => _store = new OricFileStore(_dir.Path);

    public void Dispose() => _dir.Dispose();

    /// <summary>Locates tests/fixtures by walking up from the test assembly.</summary>
    private static string Fixture(string name)
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            var candidate = Path.Combine(dir.FullName, "fixtures", name);
            if (File.Exists(candidate)) return candidate;
            dir = dir.Parent;
        }
        throw new FileNotFoundException(
            $"Fixture '{name}' not found — regenerate with: dotnet run --project tools/FixtureGen -- tests/fixtures");
    }

    private AuthorViewModel CreateAuthor()
        => new(_dialogs, _lifetime, _clipboard, _store,
            new AppMeta("Oric Author", "1.0.0", OricFileKind.Author));

    private CalcViewModel CreateCalc()
        => new(_dialogs, _lifetime, _store,
            new AppMeta("Oric Calc", "1.0.0", OricFileKind.Calc));

    private BaseViewModel CreateBase()
        => new(_dialogs, _lifetime, _store,
            new AppMeta("Oric Base", "1.0.0", OricFileKind.Base));

    // ------------------------------------------------------------ store level

    [Fact]
    public void AuthorFixture_LoadsWithTextImageAndTable()
    {
        var doc = _store.Load(Fixture("author.oau"));

        Assert.Equal("Oric Author Sample", doc.Title);
        Assert.Contains("word wrap and word count", doc.Text.Body);
        Assert.Contains("\n\n", doc.Text.Body); // paragraph break survives
        Assert.Single(doc.Text.Images);
        Assert.False(doc.Text.Images[0].IsEmpty);
        var table = Assert.Single(doc.Text.Tables);
        Assert.Equal("People", table.Name);
        Assert.Equal("Geoff", table.TextAt(1, 0));
        Assert.Equal("#DDEBF7", table.FillAt(0, 0));
    }

    [Fact]
    public void CalcFixture_LoadsWithFormulaAndImage()
    {
        var doc = _store.Load(Fixture("calc.oca"));

        Assert.Equal("Oric Calc Sample", doc.Title);
        Assert.Equal("Item", doc.Sheet.RawAt(0, 0));
        Assert.Equal("12.5", doc.Sheet.ValueAt(1, 1));
        Assert.Equal("=SUM(B2:B3)", doc.Sheet.RawAt(3, 1));
        Assert.Equal("42.5", doc.Sheet.ValueAt(3, 1));
        Assert.Single(doc.Sheet.Images);
        Assert.True(doc.Sheet.RowCount >= 40);
    }

    [Fact]
    public void BaseFixture_LoadsWithTypedFieldsAndRecords()
    {
        var doc = _store.Load(Fixture("base.oba"));

        Assert.Equal("Oric Base Sample", doc.Title);
        Assert.Equal("People", doc.Table.Name);
        Assert.Equal(3, doc.Table.Fields.Count);
        Assert.Equal(FieldType.Date, doc.Table.Fields[1].Type);
        Assert.Equal(FieldType.Number, doc.Table.Fields[2].Type);
        Assert.Equal(4, doc.Table.Records.Count);
        Assert.Equal("Geoff Phillips", doc.Table.Records[0].Get("Name"));
        Assert.Equal("760", doc.Table.Records[3].Get("Sales"));
    }

    // ------------------------------------------------------------ module imports

    [Fact]
    public void AuthorModule_ImportsItsFixture()
    {
        var vm = CreateAuthor();
        Assert.True(vm.TryOpenRecent(Fixture("author.oau")));

        Assert.Contains("word wrap and word count", vm.Body);
        Assert.Equal("Oric Author Sample", vm.Title);
        Assert.Single(vm.Doc.Text.Images);
        Assert.Equal("People", vm.Doc.Text.Tables[0].Name);
        Assert.False(vm.IsDirty);
    }

    [Fact]
    public void CalcModule_ImportsItsFixture()
    {
        var vm = CreateCalc();
        Assert.True(vm.TryOpenRecent(Fixture("calc.oca")));

        Assert.Equal("Item", vm.CellAt(0, 0).Display);
        Assert.Equal("42.5", vm.CellAt(3, 1).Display); // formula result shown
        Assert.Single(vm.Doc.Sheet.Images);
        Assert.Equal("Oric Calc Sample", vm.Title);
    }

    [Fact]
    public void BaseModule_ImportsItsFixture()
    {
        var vm = CreateBase();
        Assert.True(vm.TryOpenRecent(Fixture("base.oba")));

        Assert.Equal(3, vm.Fields.Count);
        Assert.Equal(new[] { "Name", "Joined", "Sales" }, vm.FieldNames);
        Assert.Equal(4, vm.Records.Count);
        Assert.Equal("Oric Base Sample", vm.Title);
    }

    // ------------------------------------------------------------ cross-module

    [Fact]
    public void CalcModule_OpensAuthorFile_AndPreservesItsSections()
    {
        var vm = CreateCalc();
        Assert.True(vm.TryOpenRecent(Fixture("author.oau")));

        // Calc's own view is empty…
        Assert.Equal("A1", vm.SelectedCell!.Address);
        // …but the Author section rides along untouched for a faithful re-save.
        Assert.Contains("word wrap and word count", vm.Doc.Text.Body);
        Assert.Single(vm.Doc.Text.Tables);
    }

    [Fact]
    public void AuthorModule_OpensBaseFile_ConvertingRecordsAndPreservingThem()
    {
        var vm = CreateAuthor();
        Assert.True(vm.TryOpenRecent(Fixture("base.oba")));

        // The designed cross-module behaviour: records become readable text…
        Assert.Contains("Geoff Phillips", vm.Body);
        // …while the Base section rides along untouched for a faithful re-save.
        Assert.Equal(4, vm.Doc.Table.Records.Count);
        Assert.Equal(3, vm.Doc.Table.Fields.Count);
    }

    [Fact]
    public void BaseModule_OpensCalcFile_ConvertingGridAndPreservingIt()
    {
        var vm = CreateBase();
        Assert.True(vm.TryOpenRecent(Fixture("calc.oca")));

        // The designed cross-module behaviour: the grid becomes a table…
        Assert.NotEmpty(vm.Records);
        // …while the Calc section rides along untouched.
        Assert.Equal("=SUM(B2:B3)", vm.Doc.Sheet.RawAt(3, 1));
        Assert.Single(vm.Doc.Sheet.Images);
    }

    [Fact]
    public void ImportedAuthorFixture_RoundTripsThroughSave()
    {
        var vm = CreateAuthor();
        Assert.True(vm.TryOpenRecent(Fixture("author.oau")));

        var target = _dir.File("roundtrip" + OricFileKind.Author.For());
        _dialogs.SavePath = target;
        vm.SaveAsCommand.ExecuteAsync(null).GetAwaiter().GetResult();

        var reloaded = _store.Load(target);
        Assert.Equal("Oric Author Sample", reloaded.Title);
        Assert.Equal(vm.Body, reloaded.Text.Body);
        Assert.Single(reloaded.Text.Images);
        Assert.Equal("People", reloaded.Text.Tables[0].Name);
    }
}
